class SessionHookTests(unittest.TestCase):

    def test_session_hook_list_is_reusable(self):
        def first(value):
            return value + ['first']

        def second(value):
            value.append('second')

        callbacks = [first, second]
        with Session(hooks={'response': callbacks}) as session:
            for unused in range(2):
                request = session.get('http://example.com/',
                                      return_response=False)
                self.assertEqual(
                    dispatch_hook('response', request.hooks, []),
                    ['first', 'second'])
                request.deregister_hook('response', first)
                self.assertEqual(session.hooks['response'], [first, second])
                self.assertEqual(callbacks, [first, second])

    def test_request_hooks_override_session_defaults(self):
        def default(value):
            return value + ['default']

        def local(value):
            return value + ['local']

        with Session(hooks={'response': [default]}) as session:
            for hooks, expected in ((local, ['local']),
                                    ([local, local], ['local', 'local']),
                                    ([], [])):
                request = session.get('http://example.com/',
                                      hooks={'response': hooks},
                                      return_response=False)
                self.assertEqual(
                    dispatch_hook('response', request.hooks, []), expected)
                self.assertEqual(session.hooks['response'], [default])

    def test_session_args_hook_list_runs_in_order(self):
        def first(args):
            args['headers']['X-Hook-Order'] = 'first'
            return args

        def second(args):
            args['headers']['X-Hook-Order'] += ',second'

        with Session(hooks={'args': [first, second]}) as session:
            request = session.get('http://example.com/',
                                  return_response=False)
            self.assertEqual(request.headers['X-Hook-Order'], 'first,second')


